---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Decision prompt: The agent asks a few quick questions before it starts.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change decision-prompt.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './decision-prompt.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="decision-prompt" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="dpx panel" tabindex="0">
  <div class="dpx-h"><span class="dpx-k muted num">Question 1 of 3</span><div class="dpx-dots"><i class="on"></i><i></i><i></i></div></div>
  <div class="dpx-body"></div>
  <div class="dpx-f"><button class="pill ghost sm dpx-skip">Skip</button><button class="pill primary sm dpx-go">Continue <span class="kbd">↵</span></button></div>
</div>
  </Fragment></div>
</div>
<script>
  import './decision-prompt.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Decision prompt ---------- */
/* the agent asks in the chat: no container; with .panel it becomes a card. Each answer is a tile to pick (a click, its
   number or the arrows): white with a dimmed grey edge, the picked one's edge a step stronger and its number filled. No
   room is kept for what comes next (owner, 18 Nov): the card grows and shrinks with what it shows (grow()), and once every
   question is answered the line saying the agent has started takes the buttons' place */
.dpx{padding:var(--dm-s-4) 0;display:flex;flex-direction:column;gap:var(--dm-s-3);outline:0;border-radius:var(--dm-r-in)}
.dpx.panel{padding:var(--dm-s-4);border-radius:var(--dm-r-card)}
.dpx:focus-visible{outline:2px solid var(--dm-focus);outline-offset:6px}
.dpx-h{display:flex;align-items:center;justify-content:space-between}
.dpx-k{font-size:12px;line-height:16px}
.dpx-dots{display:flex;gap:var(--dm-s-1);transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t) var(--dm-ease),visibility 0s}
/* the steps are done once every question is answered (owner, 21 Nov): the dots fade and shrink a little where they are, at
   the style's own pace, and keep their room, so nothing else in the head moves; with reduced motion they are simply gone */
.dpx-dots.gone{opacity:0;transform:scale(.8);visibility:hidden;transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t) var(--dm-ease),visibility 0s var(--dm-t)}
@media (prefers-reduced-motion:reduce){.dpx-dots,.dpx-dots.gone{transition:none}}
.dpx-dots i{width:6px;height:6px;border-radius:var(--dm-r-tiny,3px);background:var(--dm-line);transition:width .45s var(--dm-ease),background .35s}
.dpx-dots i.on{width:16px;background:var(--dm-accent-mark,var(--dm-accent))}
.dpx-dots i.done{background:var(--dm-accent-mark,var(--dm-accent));opacity:.4}
.dpx-q{font-size:14px;font-weight:500;line-height:20px;margin-bottom:var(--dm-s-3);text-wrap:balance}
.dpx-opts{display:flex;flex-direction:column;gap:6px}
.dpx-o{display:flex;align-items:center;gap:10px;width:100%;min-height:40px;padding:6px 12px 6px 10px;border-radius:var(--dm-r-in);font-size:13.5px;text-align:left;color:var(--dm-fg2);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent);transition:background-color .25s,color .25s,box-shadow .25s}
@media (hover:hover) and (pointer:fine){.dpx-o:hover{background:var(--dm-row);color:var(--dm-fg)}}
.dpx-o.on{color:var(--dm-fg);box-shadow:inset 0 0 0 1px var(--dm-pick-on)}
.dpx-o .kbd{width:20px;flex:none;text-align:center;transition:background .25s,color .25s}
.dpx-o.on .kbd{background:var(--dm-accent);color:var(--dm-on-accent)}
.dpx-o .d{margin-left:auto;font-size:12px;color:var(--dm-muted)}
.dpx-f{display:flex;align-items:center;justify-content:flex-end;gap:6px;min-height:28px}
/* the footer, its buttons or the line saying the agent has started, sits under a hairline in Soft and Blueprint (owner, 21 Nov:
   "add a divider line above the loading text"), 16px under the content and 16px over what it holds, as the card's own edges
   are; Clean's foot strip has its own (below) */
.dpx-f{margin-top:var(--dm-s-1);padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
/* Continue's Enter key is a glyph beside its word, with no tile of its own (owner, 21 Nov: "not a fan of a squircle button
   inside a rounded button"): the same gap as an icon's, and the button's padding even at both ends */
.dpx-f .pill.dpx-go .kbd{min-width:0;height:auto;padding:0;margin:0;border-radius:0;background:none;box-shadow:none;color:inherit;font-size:13px;line-height:1}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.dpx .pill:active{transform:none}
.dpx-sum{display:flex;flex-direction:column}
.dpx-sr{display:flex;gap:10px;font-size:13px;line-height:20px;padding:8px 0;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dpx-sr:first-child{padding-top:0}
.dpx-sr:last-child{border:0;padding-bottom:0}
.dpx-sr span{color:var(--dm-muted);width:92px;flex:none}
/* answered: the line saying the agent has started, where the buttons were, its mark on the content's left edge; a tick
   once it has started is the vivid mark green */
.dpx-f.run{justify-content:flex-start}
.dpx-run{display:flex;align-items:center;gap:var(--dm-s-2);min-width:0;font-size:13px;line-height:20px}
.dpx-ok{display:grid;color:var(--dm-ok-mark)}
/* Clean (owner, 19 Nov): its content 16px from every edge, and an off-white foot strip whose buttons sit 8px from the card's
   edges, round in its 22px corners; the strip starts 16px under the answers. The answers are 10px round tiles with a
   hairline, the picked one's a step stronger and its number in ink, and the progress dots are the accent, white in dark mode, as
   every Clean loader is. Continue is the ink button, its Enter key in a quiet chip of its own ink. Once answered, the strip holds the
   line saying the agent has started, its words 16px in */
:root[data-style="clean"] .dpx.panel,:root [data-style="clean"] .dpx.panel,:root [data-style="clean"].dpx.panel{padding:16px 16px 0}
:root[data-style="clean"] .dpx-dots i,:root [data-style="clean"] .dpx-dots i,:root [data-style="clean"].dpx-dots i{background:var(--dm-rail);transition:width var(--dm-t) var(--dm-ease),background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dpx-dots i.on,:root [data-style="clean"] .dpx-dots i.on,:root [data-style="clean"].dpx-dots i.on{background:var(--dm-accent-mark)}
:root[data-style="clean"] .dpx-dots i.done,:root [data-style="clean"] .dpx-dots i.done,:root [data-style="clean"].dpx-dots i.done{background:var(--dm-accent-mark);opacity:.3}
:root[data-style="clean"] .dpx-run .think,:root [data-style="clean"] .dpx-run .think,:root [data-style="clean"].dpx-run .think{color:var(--dm-accent-mark)}
:root[data-style="clean"] .dpx-o,:root [data-style="clean"] .dpx-o,:root [data-style="clean"].dpx-o{border-radius:10px;box-shadow:inset 0 0 0 1px var(--dm-hair);transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dpx-o.on,:root [data-style="clean"] .dpx-o.on,:root [data-style="clean"].dpx-o.on{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-fg) 26%,transparent)}
:root[data-style="clean"] .dpx-o .kbd,:root [data-style="clean"] .dpx-o .kbd,:root [data-style="clean"].dpx-o .kbd{transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dpx-o.on .kbd,:root [data-style="clean"] .dpx-o.on .kbd,:root [data-style="clean"].dpx-o.on .kbd{background:var(--dm-fg);color:var(--dm-surface)}
:root[data-style="clean"] .dpx.panel .dpx-f,:root [data-style="clean"] .dpx.panel .dpx-f,:root [data-style="clean"].dpx.panel .dpx-f{margin:4px -16px 0;padding:8px 16px;gap:4px;min-height:45px;border-top:1px solid var(--dm-line);background:var(--dm-strip);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .dpx.panel .dpx-f.run,:root [data-style="clean"] .dpx.panel .dpx-f.run,:root [data-style="clean"].dpx.panel .dpx-f.run{padding-left:16px}
/* (a step of --dm-ok in the vivid green keeps the tick at 3:1 on the off-white strip, as Attachment tray's does) */
:root[data-style="clean"] .dpx.panel .dpx-ok,:root [data-style="clean"] .dpx.panel .dpx-ok,:root [data-style="clean"].dpx.panel .dpx-ok{color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, enter, giveBack, grow, stagger } from '../core/core.js';
DM.def('decision-prompt', (r, c) => {
  const Q = [
    ['Which frames should the agent redesign?', 'Frames', [['Pricing only','1 frame'],['Pricing and checkout','3 frames'],['The whole flow','9 frames']]],
    ['How bold can the changes be?', 'Scope', [['Polish spacing and type','Safe'],['Rework the layout','Medium'],['Fresh direction','Bold']]],
    ['Where should the result go?', 'Output', [['New Figma page','Keeps the original'],['Branch in the repo','Opens a PR'],['Both','Recommended']]]
  ];
  const ans = []; let qi = 0, sel = 0, done = false;
  const body = $('.dpx-body', r), k = $('.dpx-k', r), dots = $$('.dpx-dots i', r), go = $('.dpx-go', r), skip = $('.dpx-skip', r), card = $('.dpx', r), foot = $('.dpx-f', r);
  // no room is kept for the next question or the summary: the card grows and shrinks with them, once its entrance (which
  // scales it from .98 in Clean) has ended, so it measures the card at its real size
  Promise.resolve().then(() => Promise.all(card.getAnimations().map(a => a.finished.catch(() => {})))).then(() => { if (!c.dead && card.isConnected) c.offs.push(grow(card)); });
  function paint(){
    k.textContent = 'Question ' + (qi + 1) + ' of 3';
    dots.forEach((d, i) => { d.classList.toggle('on', i === qi); d.classList.toggle('done', i < qi); });
    const q = Q[qi];
    body.innerHTML = `<div class="dpx-q">${q[0]}</div><div class="dpx-opts" role="radiogroup" aria-label="${q[0]}">` + q[2].map((o, i) => `<button class="dpx-o${i === sel ? ' on' : ''}" role="radio" aria-checked="${i === sel}" data-i="${i}"><span class="kbd">${i + 1}</span>${o[0]}<span class="d">${o[1]}</span></button>`).join('') + '</div>';
    // the next question plays its entrance; the first comes in with the card's own entrance and is drawn from the start, so a
    // frame that doesn't animate yet (a small live preview off screen, as on the docs' Introduction) still shows it
    if (qi){ enter($('.dpx-q', body)); stagger($$('.dpx-o', body), 50, 60); }
    $$('.dpx-o', body).forEach(b => { b.onclick = () => choose(+b.dataset.i); b.ondblclick = next; });
  }
  function choose(i){ sel = i; $$('.dpx-o', body).forEach((b, j) => { b.classList.toggle('on', j === i); b.setAttribute('aria-checked', j === i); }); }
  function next(skipped){
    if (done) return; ans.push(skipped === true ? 'Agent decides' : Q[qi][2][sel][0]); qi++; sel = 0;
    if (qi < Q.length) return paint();
    // the steps are over: the dots fade away where they are (owner, 21 Nov), and the head keeps its place
    done = true; dots.forEach(d => { d.classList.remove('on'); d.classList.add('done'); }); $('.dpx-dots', r).classList.add('gone'); k.textContent = 'All set';
    // the buttons give way to the line saying the agent has started (its words shimmer while it gets going); a focus that
    // was on them comes back to the card
    const had = foot.contains(document.activeElement);
    body.innerHTML = `<div class="dpx-sum">${Q.map((q, i) => `<div class="dpx-sr"><span>${q[1]}</span>${ans[i]}</div>`).join('')}</div>`;
    foot.classList.add('run'); foot.innerHTML = `<div class="dpx-run" aria-live="polite"><span class="think on"><i></i><i></i><i></i><i></i></span><span class="shim">Starting the redesign</span></div>`;
    if (had) giveBack(card);
    stagger([...$$('.dpx-sr', body), $('.dpx-run', foot)], 70);
  }
  go.onclick = () => next(); skip.onclick = () => next(true);
  c.on(card, 'keydown', e => { if (done) return; if (/^[1-3]$/.test(e.key)){ choose(+e.key - 1); e.preventDefault(); } else if (e.key === 'Enter'){ next(); e.preventDefault(); } else if (e.key === 'ArrowDown' || e.key === 'ArrowUp'){ choose((sel + (e.key === 'ArrowDown' ? 1 : 2)) % 3); e.preventDefault(); } });
  paint();
});
